import type { Language } from '@/i18n/translations';

/**
 * 多语言文本对象
 */
export interface I18nText {
  en: string;
  zh: string;
  es: string;
  ja: string;
}

/**
 * 从多语言对象中获取当前语言的值，缺失时回退到英文
 */
export function getI18nValue(
  val: I18nText | string | undefined | null,
  lang: Language,
  fallbackLang: Language = 'en',
): string {
  if (!val) return '';
  if (typeof val === 'string') return val;
  const target = val[lang];
  if (target && target.trim()) return target;
  return val[fallbackLang] ?? val.en ?? '';
}

/**
 * 创建 I18nText 对象
 */
export function createI18nText(en: string, zh = '', es = '', ja = ''): I18nText {
  return { en, zh, es, ja };
}

/**
 * 旧数据迁移：单语言字符串 -> I18nText 对象
 * 空值安全处理
 */
export function migrateI18n(val: string | I18nText | undefined | null): I18nText {
  if (!val) return { en: '', zh: '', es: '', ja: '' };
  if (typeof val === 'string') return { en: val, zh: '', es: '', ja: '' };
  // 已经是对象则补全缺失的 key
  return {
    en: val.en ?? '',
    zh: val.zh ?? '',
    es: val.es ?? '',
    ja: val.ja ?? '',
  };
}

/**
 * 数组版本的迁移
 */
export function migrateI18nArray(
  arr: (string | I18nText)[] | undefined | null,
): I18nText[] {
  if (!arr || !Array.isArray(arr)) return [];
  return arr.map(migrateI18n);
}

/**
 * 判断一个值是否已经是多语言对象
 */
export function isI18nText(val: unknown): val is I18nText {
  return (
    typeof val === 'object' &&
    val !== null &&
    'en' in (val as Record<string, unknown>)
  );
}
